import{_ as e,o as a,c as i,a5 as s}from"./chunks/framework.DrDMl0tG.js";const r="/assets/voxel_ray_casting_cpu.BJrPqajU.svg",d="/assets/voxel_ray_casting_gpu.jTjX_dni.svg",n="/assets/voxel_ray_casting_scan.CLSlpHn2.svg",l="/assets/voxel_ray_casting_robot.DAuSyHMM.svg",h="/assets/voxel_ray_casting_edits.BIh-yngp.svg",u=JSON.parse('{"title":"Voxel Ray Casting","description":"","frontmatter":{},"headers":[],"relativePath":"sections/BenchmarkVoxelRayCasting.md","filePath":"sections/BenchmarkVoxelRayCasting.md"}'),g={name:"sections/BenchmarkVoxelRayCasting.md"};function o(y,t,x,c,p,m){return a(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="voxel-ray-casting" tabindex="-1">Voxel Ray Casting <a class="header-anchor" href="#voxel-ray-casting" aria-label="Permalink to &quot;Voxel Ray Casting&quot;">​</a></h1><p>RaiSim&#39;s <a href="./VoxelMap.html">voxel map</a> ray cast is compared with the voxel libraries robotics and graphics code commonly use, on the CPU and on the GPU, with the same scenes and the same rays.</p><ul><li><strong>CPU:</strong> RaiSim casts a lidar ray in <strong>172–301 ns</strong>, <strong>1.7–2.0×</strong> faster than NanoVDB, <strong>3.3–4.0×</strong> faster than OpenVDB, <strong>4.7–9.5×</strong> faster than Bonxai and <strong>22–34×</strong> faster than OctoMap. RaiSim and OpenVDB return every hit exactly; NanoVDB&#39;s ray marcher reports a different voxel or distance for 84–97 % of the rays.</li><li><strong>GPU:</strong> <a href="./Rayrai.html">rayrai</a>&#39;s GPU LiDAR casts a ray in <strong>0.9–3.3 ns</strong>, <strong>1.3–1.8×</strong> faster than NanoVDB in CUDA, and returns the CPU&#39;s points ray by ray.</li><li><strong>CPU and GPU:</strong> a 65,536-ray scan takes <strong>11–20 ms</strong> on one CPU core and <strong>0.41–0.57 ms</strong> with rayrai, <strong>27–34×</strong> faster.</li><li><strong>Edits:</strong> after carving or filling a sphere, rayrai uploads only the parts of the map that changed. The next scan takes <strong>0.44–0.56 ms</strong>, about as long as any other scan. NanoVDB has to rebuild and upload the whole grid, which takes <strong>7.0–18.5 ms</strong>.</li></ul><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>CPU</td><td>AMD Ryzen 9 3950X, one thread pinned to one core, Linux x86-64, Clang 20 Release (<code>-O3 -march=x86-64-v3</code>)</td></tr><tr><td>GPU</td><td>NVIDIA GeForce RTX 2070 SUPER, driver 580.178.04, OpenGL 4.3 (rayrai) and CUDA 13.3</td></tr><tr><td>Libraries</td><td>OpenVDB 14.0.0 and the NanoVDB 32.11.0 it ships, Bonxai 0.8.0, OctoMap 1.10.0</td></tr></tbody></table><p>Each library casts rays with its own ray routine: OpenVDB&#39;s <code>VolumeRayIntersector</code> with its <code>DDA</code> inside leaves, NanoVDB&#39;s <code>firstActive</code> (its hierarchical DDA, the same code on the CPU and in CUDA), Bonxai&#39;s <code>ExactRayIterator</code> and OctoMap&#39;s <code>castRay</code>. A dense bit grid stepped voxel by voxel (<code>dense DDA</code>) is the reference: every other result is compared with it, ray by ray. The grids are built from the same list of occupied voxels.</p><table tabindex="0"><thead><tr><th>Scene</th><th style="text-align:right;">Voxel</th><th>Size</th><th style="text-align:right;">Occupied voxels</th><th>Contents</th></tr></thead><tbody><tr><td>terrain</td><td style="text-align:right;">0.10 m</td><td>51 m × 51 m × 10 m</td><td style="text-align:right;">7.6 M</td><td>hills, 40 buildings, 10 platforms on legs, 6 tunnels</td></tr><tr><td>indoor</td><td style="text-align:right;">0.05 m</td><td>30 m × 30 m × 9 m</td><td style="text-align:right;">6.2 M</td><td>three storeys of 25 rooms with doors, windows, stairs and furniture</td></tr><tr><td>forest</td><td style="text-align:right;">0.10 m</td><td>100 m × 100 m × 13 m</td><td style="text-align:right;">9.7 M</td><td>600 trees with hollow crowns and 200 boulders on rolling ground</td></tr></tbody></table><p>Each scene is scanned by eight lidars at random free positions, 1,024 × 64 rays each over pitch −25° to 15° with a 100 m range (524,288 rays), and by 200,000 rays from random free points in random directions with a 50 m range.</p><h2 id="cpu" tabindex="-1">CPU <a class="header-anchor" href="#cpu" aria-label="Permalink to &quot;CPU&quot;">​</a></h2><img class="diagram" src="'+r+'" alt="Bar chart of lidar rays per second on one CPU core, one panel per scene. RaiSim casts the most in every scene, then NanoVDB, whose hits differ for most rays, OpenVDB, the dense grid, Bonxai and OctoMap. The table below gives the times."><p><strong>Nanoseconds per ray, one thread; lower is better.</strong> Median of five runs.</p><table tabindex="0"><thead><tr><th>Scene</th><th>Rays</th><th style="text-align:right;">RaiSim</th><th style="text-align:right;">NanoVDB</th><th style="text-align:right;">OpenVDB</th><th style="text-align:right;">Bonxai</th><th style="text-align:right;">OctoMap</th><th style="text-align:right;">dense DDA</th></tr></thead><tbody><tr><td>terrain</td><td>lidar</td><td style="text-align:right;"><strong>212</strong></td><td style="text-align:right;">382</td><td style="text-align:right;">854</td><td style="text-align:right;">2,015</td><td style="text-align:right;">7,205</td><td style="text-align:right;">1,041</td></tr><tr><td></td><td>random</td><td style="text-align:right;"><strong>251</strong></td><td style="text-align:right;">409</td><td style="text-align:right;">663</td><td style="text-align:right;">3,704</td><td style="text-align:right;">10,320</td><td style="text-align:right;">1,022</td></tr><tr><td>indoor</td><td>lidar</td><td style="text-align:right;"><strong>172</strong></td><td style="text-align:right;">293</td><td style="text-align:right;">571</td><td style="text-align:right;">1,268</td><td style="text-align:right;">5,237</td><td style="text-align:right;">1,004</td></tr><tr><td></td><td>random</td><td style="text-align:right;"><strong>272</strong></td><td style="text-align:right;">396</td><td style="text-align:right;">643</td><td style="text-align:right;">1,068</td><td style="text-align:right;">3,712</td><td style="text-align:right;">715</td></tr><tr><td>forest</td><td>lidar</td><td style="text-align:right;"><strong>301</strong></td><td style="text-align:right;">592</td><td style="text-align:right;">1,108</td><td style="text-align:right;">1,401</td><td style="text-align:right;">6,470</td><td style="text-align:right;">1,380</td></tr><tr><td></td><td>random</td><td style="text-align:right;"><strong>337</strong></td><td style="text-align:right;">538</td><td style="text-align:right;">921</td><td style="text-align:right;">2,643</td><td style="text-align:right;">8,126</td><td style="text-align:right;">1,076</td></tr></tbody></table><p><strong>Lidar rays that differ from the reference</strong> (a missed or extra hit, another voxel, or another distance):</p><table tabindex="0"><thead><tr><th>Scene</th><th style="text-align:right;">RaiSim</th><th style="text-align:right;">NanoVDB</th><th style="text-align:right;">OpenVDB</th><th style="text-align:right;">Bonxai</th><th style="text-align:right;">OctoMap</th></tr></thead><tbody><tr><td>terrain</td><td style="text-align:right;">0</td><td style="text-align:right;">84.4 %</td><td style="text-align:right;">0</td><td style="text-align:right;">1.8 %</td><td style="text-align:right;">2 rays</td></tr><tr><td>indoor</td><td style="text-align:right;">0</td><td style="text-align:right;">96.8 %</td><td style="text-align:right;">0</td><td style="text-align:right;">1.4 %</td><td style="text-align:right;">0</td></tr><tr><td>forest</td><td style="text-align:right;">0</td><td style="text-align:right;">93.0 %</td><td style="text-align:right;">0</td><td style="text-align:right;">3.1 %</td><td style="text-align:right;">4 rays</td></tr></tbody></table><p>NanoVDB&#39;s <code>firstActive</code> returns where its DDA steps into a voxel rather than the voxel&#39;s face, one to two voxels too far on average, and it steps into a voxel beside the ray at some edges and corners. Bonxai&#39;s iterator does the same at 1–3 % of the rays. OctoMap works in single precision. RaiSim reports the face the ray enters, and a ray along an edge or through a corner enters only the voxels beyond it (see <a href="./VoxelMap.html#ray-tests">Ray tests</a>).</p><p><strong>Building the grid and its memory:</strong></p><table tabindex="0"><thead><tr><th>Scene</th><th></th><th style="text-align:right;">RaiSim</th><th style="text-align:right;">NanoVDB</th><th style="text-align:right;">OpenVDB</th><th style="text-align:right;">Bonxai</th><th style="text-align:right;">OctoMap</th><th style="text-align:right;">dense DDA</th></tr></thead><tbody><tr><td>terrain</td><td>build (ms)</td><td style="text-align:right;">32</td><td style="text-align:right;">50</td><td style="text-align:right;">43</td><td style="text-align:right;">37</td><td style="text-align:right;">1,251</td><td style="text-align:right;">37</td></tr><tr><td></td><td>memory (MB)</td><td style="text-align:right;">2.1</td><td style="text-align:right;">4.8</td><td style="text-align:right;">4.5</td><td style="text-align:right;">13.5</td><td style="text-align:right;">28.3</td><td style="text-align:right;">3.3</td></tr><tr><td>indoor</td><td>build (ms)</td><td style="text-align:right;">30</td><td style="text-align:right;">48</td><td style="text-align:right;">41</td><td style="text-align:right;">37</td><td style="text-align:right;">993</td><td style="text-align:right;">28</td></tr><tr><td></td><td>memory (MB)</td><td style="text-align:right;">8.5</td><td style="text-align:right;">8.0</td><td style="text-align:right;">7.4</td><td style="text-align:right;">25.5</td><td style="text-align:right;">30.5</td><td style="text-align:right;">7.9</td></tr><tr><td>forest</td><td>build (ms)</td><td style="text-align:right;">74</td><td style="text-align:right;">102</td><td style="text-align:right;">91</td><td style="text-align:right;">100</td><td style="text-align:right;">1,765</td><td style="text-align:right;">47</td></tr><tr><td></td><td>memory (MB)</td><td style="text-align:right;">17.0</td><td style="text-align:right;">18.6</td><td style="text-align:right;">17.2</td><td style="text-align:right;">57.6</td><td style="text-align:right;">254.3</td><td style="text-align:right;">15.6</td></tr></tbody></table><p>The dense grid&#39;s memory grows with the volume of its domain; the others grow with the occupied voxels.</p><h2 id="gpu" tabindex="-1">GPU <a class="header-anchor" href="#gpu" aria-label="Permalink to &quot;GPU&quot;">​</a></h2><img class="diagram" src="'+d+'" alt="Bar chart of voxel rays per second on the GPU, one panel per scene. rayrai casts the most in every scene, then NanoVDB in CUDA, whose hits differ for most rays, and the dense grid in CUDA. The table below gives the times."><p><strong>Nanoseconds per ray for the voxel pass alone; lower is better.</strong> Median of five runs, rayrai and CUDA taking turns, 524,288 lidar rays per scene. rayrai&#39;s pass is timed with an OpenGL timer query, the CUDA kernels with CUDA events.</p><table tabindex="0"><thead><tr><th>Scene</th><th style="text-align:right;">rayrai (OpenGL)</th><th style="text-align:right;">NanoVDB (CUDA)</th><th style="text-align:right;">dense DDA (CUDA)</th></tr></thead><tbody><tr><td>terrain</td><td style="text-align:right;"><strong>1.46</strong></td><td style="text-align:right;">2.58</td><td style="text-align:right;">5.31</td></tr><tr><td>indoor</td><td style="text-align:right;"><strong>0.92</strong></td><td style="text-align:right;">1.31</td><td style="text-align:right;">4.19</td></tr><tr><td>forest</td><td style="text-align:right;"><strong>3.31</strong></td><td style="text-align:right;">4.45</td><td style="text-align:right;">9.78</td></tr></tbody></table><p><strong>Rays that differ from RaiSim&#39;s CPU ray cast:</strong></p><table tabindex="0"><thead><tr><th>Scene</th><th style="text-align:right;">rayrai</th><th style="text-align:right;">NanoVDB</th><th style="text-align:right;">dense DDA</th></tr></thead><tbody><tr><td>terrain</td><td style="text-align:right;">0</td><td style="text-align:right;">84.0 %</td><td style="text-align:right;">0</td></tr><tr><td>indoor</td><td style="text-align:right;">0</td><td style="text-align:right;">96.1 %</td><td style="text-align:right;">0</td></tr><tr><td>forest</td><td style="text-align:right;">1 ray</td><td style="text-align:right;">92.4 %</td><td style="text-align:right;">2 rays</td></tr></tbody></table><p>rayrai works in single precision, so a ray that passes within rounding of a voxel edge can enter or skip the voxel beside it; one ray in 1.5 million did.</p><h2 id="cpu-and-gpu" tabindex="-1">CPU and GPU <a class="header-anchor" href="#cpu-and-gpu" aria-label="Permalink to &quot;CPU and GPU&quot;">​</a></h2><p>A full 65,536-ray scan through rayrai&#39;s GPU LiDAR (<code>measureSpinningLidarSingleDrawGPU</code>) includes building the ray table, drawing every body and reading the ranges back (median of five runs, in the same runs as the <a href="#edits">edits</a>):</p><img class="diagram" src="'+n+'" alt="Bar chart of the milliseconds one 65,536-ray scan takes, one panel per scene: tens of milliseconds for RaiSim on one CPU core, under a millisecond for rayrai on the GPU. The table below gives the times."><table tabindex="0"><thead><tr><th>Scene</th><th style="text-align:right;">CPU (RaiSim, one thread)</th><th style="text-align:right;">GPU (rayrai), GPU time</th><th style="text-align:right;">GPU (rayrai), wall clock</th><th style="text-align:right;">Speedup</th></tr></thead><tbody><tr><td>terrain</td><td style="text-align:right;">13.9 ms</td><td style="text-align:right;">0.39 ms</td><td style="text-align:right;">0.44 ms</td><td style="text-align:right;">32×</td></tr><tr><td>indoor</td><td style="text-align:right;">11.3 ms</td><td style="text-align:right;">0.37 ms</td><td style="text-align:right;">0.41 ms</td><td style="text-align:right;">27×</td></tr><tr><td>forest</td><td style="text-align:right;">19.7 ms</td><td style="text-align:right;">0.52 ms</td><td style="text-align:right;">0.57 ms</td><td style="text-align:right;">34×</td></tr></tbody></table><p>On a robot, <code>rayrai_lidar_benchmark</code> scans an 84 m × 84 m terrain with 200 obstacles with an Ouster OS1-64 (512 × 64 rays per turn, 10 turns per second) on ANYmal. The two lidars are twins and return the same points; no return differs. The chart adds up the time per second of simulated time; the table gives it per update. Medians of three runs:</p><img class="diagram" src="'+l+'" alt="Line charts, one per terrain, of the milliseconds of LiDAR per simulated second at 10, 100 and 1,000 updates per second. The CPU line stays flat near 100 ms; the GPU line starts far below it and rises above it at 1,000 updates per second. The table below gives the times per update."><table tabindex="0"><thead><tr><th>Terrain</th><th style="text-align:right;">Updates per second</th><th style="text-align:right;">CPU per update</th><th style="text-align:right;">GPU per update</th><th style="text-align:right;">GPU speedup</th></tr></thead><tbody><tr><td>voxel map, 0.10 m</td><td style="text-align:right;">10</td><td style="text-align:right;">9.30 ms</td><td style="text-align:right;">0.41 ms</td><td style="text-align:right;">23×</td></tr><tr><td></td><td style="text-align:right;">100</td><td style="text-align:right;">994 µs</td><td style="text-align:right;">202 µs</td><td style="text-align:right;">4.9×</td></tr><tr><td></td><td style="text-align:right;">1,000</td><td style="text-align:right;">108 µs</td><td style="text-align:right;">169 µs</td><td style="text-align:right;">0.6×</td></tr><tr><td>voxel map, 0.05 m</td><td style="text-align:right;">10</td><td style="text-align:right;">10.12 ms</td><td style="text-align:right;">0.46 ms</td><td style="text-align:right;">22×</td></tr><tr><td></td><td style="text-align:right;">100</td><td style="text-align:right;">1,075 µs</td><td style="text-align:right;">220 µs</td><td style="text-align:right;">4.9×</td></tr><tr><td></td><td style="text-align:right;">1,000</td><td style="text-align:right;">116 µs</td><td style="text-align:right;">179 µs</td><td style="text-align:right;">0.6×</td></tr><tr><td>heightmap, 0.5 m cells</td><td style="text-align:right;">10</td><td style="text-align:right;">8.92 ms</td><td style="text-align:right;">0.82 ms</td><td style="text-align:right;">11×</td></tr><tr><td></td><td style="text-align:right;">100</td><td style="text-align:right;">955 µs</td><td style="text-align:right;">231 µs</td><td style="text-align:right;">4.1×</td></tr><tr><td></td><td style="text-align:right;">1,000</td><td style="text-align:right;">103 µs</td><td style="text-align:right;">155 µs</td><td style="text-align:right;">0.7×</td></tr></tbody></table><p>A GPU update waits for its ranges to come back, about 0.15 ms, however few rays it casts. Updated every 1 ms physics step, each update casts 328 rays, which the CPU does faster; at 100 updates per second (3,277 rays each) the GPU is 4 to 5 times faster.</p><h2 id="edits" tabindex="-1">Edits <a class="header-anchor" href="#edits" aria-label="Permalink to &quot;Edits&quot;">​</a></h2><p>A sphere of 0.5 m radius is carved out of or filled into the map 3 to 7 m from the sensor, and the next scan is timed (median of five runs, rayrai and NanoVDB taking turns):</p><img class="diagram" src="'+h+`" alt="Bar chart of the milliseconds after carving or filling a sphere, one panel per scene: under a millisecond for rayrai to upload the change and scan, several to tens of milliseconds for NanoVDB to rebuild and upload its grid. The table below gives the times."><table tabindex="0"><thead><tr><th>Scene</th><th style="text-align:right;">rayrai: scan after the edit</th><th style="text-align:right;">rayrai: upload of the edit</th><th style="text-align:right;">NanoVDB: rebuild and upload</th></tr></thead><tbody><tr><td>terrain</td><td style="text-align:right;">0.47 ms</td><td style="text-align:right;">0.01–0.04 ms</td><td style="text-align:right;">7.0 ms</td></tr><tr><td>indoor</td><td style="text-align:right;">0.44 ms</td><td style="text-align:right;">0.01–0.04 ms</td><td style="text-align:right;">8.7 ms</td></tr><tr><td>forest</td><td style="text-align:right;">0.56 ms</td><td style="text-align:right;">0.01–0.04 ms</td><td style="text-align:right;">18.5 ms</td></tr></tbody></table><p>rayrai uploads only the 16³-voxel bricks the edit changed. A NanoVDB grid cannot be edited in place, so the time is that of NanoVDB&#39;s grid builder adding the sphere&#39;s voxels, converting the grid and copying it to the GPU; removing voxels needs a build from the source data. On the robot above, a turn right after an edit takes 0.44 ms with 0.10 m voxels and 0.51 ms with 0.05 m voxels.</p><h2 id="reproduce" tabindex="-1">Reproduce <a class="header-anchor" href="#reproduce" aria-label="Permalink to &quot;Reproduce&quot;">​</a></h2><p><a href="/voxel_ray_casting_results.json">Download the recorded results</a>, from which the tables and charts on this page are made. The comparisons with other libraries use an internal harness that is not distributed. RaiSim&#39;s own measurements come from the benchmark runner of the RaiSim source repository, which the binary package does not ship (see <a href="./BuildAndTest.html#timing-examples">Build, Test, and Benchmark</a>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">taskset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build-benchmark/benchmark/benchmarks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> voxel_lidar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> voxel_contacts</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> voxel_edit</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --raisim</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">taskset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build-benchmark/visualizer/rayrai/rayrai_lidar_benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --voxel-size=0.1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">taskset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build-benchmark/visualizer/rayrai/rayrai_lidar_benchmark</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --voxel-size=0.05</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">taskset</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./build-benchmark/visualizer/rayrai/rayrai_lidar_benchmark</span></span></code></pre></div><p><code>voxel_lidar</code> times lidar scans of a terrain as a voxel map and as a heightmap, <code>voxel_contacts</code> a pile of bodies on voxel rubble and <code>voxel_edit</code> carving spheres out of a map. <code>rayrai_lidar_benchmark</code> prints the robot table above; without <code>--voxel-size</code> it scans the heightmap. Timings depend on the machine, compiler and driver.</p>`,42)])])}const k=e(g,[["render",o]]);export{u as __pageData,k as default};
